"""The agent stands alone and its exported workflow constants are unedited (generated by adk_v2/6.0.0)."""

import importlib
import sys
from pathlib import Path
from typing import Any

from retail_kyc_onboarding._engine.content import digest


def test_every_constant_matches_its_digest(workflow: Any):
    """No prompt, model, tool, condition or graph was edited by hand (replace them in settings.py instead)."""
    for unit in workflow.all_units():
        assert digest(unit.graph) == unit.graph_sha256, f"{unit.identity.export.id}: graph edited"
        for kind in ("prompts", "models", "tools", "conditions", "guardrails"):
            for eid, entity in getattr(unit, kind).items():
                assert digest(entity) == entity.sha256, f"{unit.identity.export.id}: {kind} {eid} edited"


def test_the_engine_is_this_packages_private_subpackage(root: Path):
    """The engine imports from the copy inside the agent folder and never under a top-level name."""
    engine = importlib.import_module("retail_kyc_onboarding._engine")
    assert Path(engine.__file__).resolve().is_relative_to(root)
    assert "kaya_adk_core" not in sys.modules, "nothing may import the engine under a top-level name"
    assert "kaya_adk_exporter" not in sys.modules and "kaya_adk_service" not in sys.modules


def test_the_agent_folder_is_what_adk_expects(root: Path):
    """`__init__.py` imports `agent` (root_agent, app); the requirements `adk deploy` installs are beside it."""
    folder = root
    assert "from . import agent" in (folder / "__init__.py").read_text()
    assert "kaya-adk" not in (folder / "requirements.txt").read_text().lower(), "no dependency on the generating platform"
    agent_files = sorted(p.relative_to(root).as_posix() for p in root.rglob("agent.py") if ".venv" not in p.parts)
    assert agent_files == ["agent.py"], "adk web lists every folder holding an agent.py"
